
.sheet {
  width: 100%;
  max-width: 560px;
  margin: 0 auto;
  background: var(--c-surface);
  backdrop-filter: var(--glass);
  -webkit-backdrop-filter: var(--glass);
  border: 1px solid rgba(255, 255, 255, 0.9);
  border-radius: 22px;
  box-shadow:
    var(--lift-hi),
    inset 0 0 0 0.5px rgba(255, 255, 255, 0.5);
  color: var(--c-text);
  font-size: 13px;
  overflow: hidden;
}

/* ── 顶部 ── */
.sheet__head {
  padding: 22px 22px 16px;
}

.sheet__title {
  font-size: 1.55rem;
  font-weight: 600;
  letter-spacing: -0.03em;
  line-height: 1.15;
  color: var(--c-text);
}

.sheet__sub {
  margin-top: 5px;
  font-size: 0.78rem;
  color: var(--c-text-muted);
  letter-spacing: 0.005em;
}

.steps {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 16px;
}

.steps__dot {
  width: 26px;
  height: 2px;
  border-radius: 1px;
  background: rgba(0, 0, 0, 0.09);
  transition: background 0.4s var(--ease);
}

.steps__dot--on {
  background: var(--c-text);
}

.steps__num {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 0.66rem;
  color: var(--c-text-faint);
  letter-spacing: 0.02em;
}

/* ── 表单 ── */
.form {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 0 22px 20px;
}

.page {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.row2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.split3 {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 10px;
}

/* ── 字段 ── */
.field {
  display: flex;
  flex-direction: column;
  gap: 7px;
  min-width: 0;
}

.field__label {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  color: var(--c-text-faint);
}

.field__input {
  width: 100%;
  padding: 10px 12px;
  background: var(--c-surface-sunken);
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  color: var(--c-text);
  font-family: var(--font-ui);
  font-size: 0.84rem;
  line-height: 1.5;
  outline: none;
  transition:
    background 0.2s var(--ease),
    border-color 0.2s var(--ease),
    box-shadow 0.2s var(--ease);

  &::placeholder {
    color: var(--c-text-faint);
    font-weight: 400;
  }

  &:hover {
    background: rgba(0, 0, 0, 0.04);
  }

  &:focus {
    background: var(--c-surface-raised);
    border-color: rgba(0, 113, 227, 0.5);
    box-shadow: 0 0 0 3.5px rgba(0, 113, 227, 0.1);
  }
}

.field__input--area {
  resize: vertical;
  min-height: 60px;
  font-family: var(--font-ui);
}

/* ── 带单位的小格 ── */
.cell {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.cell--narrow {
  max-width: 128px;
}

.cell__in {
  flex: 1;
  min-width: 0;
  text-align: center;
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
}

.cell__in--mono {
  letter-spacing: 0.06em;
}

.cell__unit {
  flex-shrink: 0;
  font-size: 0.72rem;
  color: var(--c-text-faint);
}

.cell__unit--mono {
  font-family: var(--font-mono);
  font-size: 0.8rem;
  color: var(--c-text-muted);
}

/* ── 分组 ── */
.group {
  padding-top: 16px;
  border-top: 0.5px solid var(--c-border);
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.group--top {
  padding-top: 0;
  border-top: none;
}

.group__h {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: var(--c-text);
}

.group__desc {
  font-size: 0.72rem;
  color: var(--c-text-faint);
  line-height: 1.65;
}

.group__note {
  font-size: 0.72rem;
  color: var(--c-text-faint);
  line-height: 1.65;
}

.group__warn {
  color: var(--c-warning);
}

/* ── 财务三卡 ── */
.money {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 14px;
  border-radius: var(--radius);
  background: var(--c-surface-sunken);
}

.money__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.money__k {
  font-size: 0.74rem;
  font-weight: 600;
  color: var(--c-text-muted);
  letter-spacing: 0.04em;
  flex-shrink: 0;
}

.money__ctrl {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.money__unit {
  font-family: var(--font-mono);
  font-size: 0.8rem;
  color: var(--c-text-faint);
  flex-shrink: 0;
}

.money__num,
.money__cycle,
.money__note {
  background: var(--c-surface-raised);
  border: 1px solid transparent;

  &:hover {
    background: var(--c-surface-raised);
  }

  &:focus {
    border-color: rgba(0, 113, 227, 0.5);
    box-shadow: 0 0 0 3.5px rgba(0, 113, 227, 0.1);
  }
}

.money__num {
  width: 116px;
  text-align: right;
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  padding: 7px 10px;
  font-size: 0.84rem;
}

.money__cycle {
  width: 78px;
  padding: 7px 6px;
  font-size: 0.76rem;
  font-family: var(--font-ui);
  color: var(--c-text-muted);
  appearance: none;
  text-align: center;
  cursor: pointer;
}

.money__cny {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  color: var(--c-text-faint);
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.money__note {
  font-size: 0.78rem;
  padding: 8px 10px;
}

/* ── 错误与导航 ── */
.err {
  font-size: 0.74rem;
  color: var(--c-danger);
  padding-top: 2px;
}

.nav {
  display: flex;
  gap: 10px;
  margin-top: 6px;
}

.nav__btn {
  flex: 1;
  padding: 12px;
  border-radius: 12px;
  font-family: var(--font-ui);
  font-size: 0.84rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition:
    background 0.2s var(--ease),
    color 0.2s var(--ease),
    border-color 0.2s var(--ease),
    opacity 0.2s var(--ease);
}

.nav__btn--main {
  border: 1px solid transparent;
  background: var(--c-text);
  color: #fff;

  &:hover:not(:disabled) {
    background: #000;
  }

  &:active:not(:disabled) {
    opacity: 0.82;
  }

  &:disabled {
    opacity: 0.32;
    cursor: default;
  }
}

.nav__btn--ghost {
  flex: 0 0 104px;
  border: 1px solid var(--c-border-strong);
  background: transparent;
  color: var(--c-text-muted);

  &:hover:not(:disabled) {
    background: rgba(0, 0, 0, 0.03);
    color: var(--c-text);
  }

  &:disabled {
    opacity: 0.35;
    cursor: default;
  }
}

@media (max-width: 520px) {
  .row2 {
    grid-template-columns: 1fr;
  }

  .sheet__head {
    padding: 18px 18px 14px;
  }

  .form {
    padding: 0 18px 18px;
  }

  .money__head {
    flex-direction: column;
    align-items: stretch;
  }

  .money__num {
    flex: 1;
    width: auto;
  }
}
